NAME = 'FinSTLK2017: Pyhä Raamattu (STLK 2017)'
BOOK = 'I Peter'

CHAPTERS = {
    1: {
        1: 'Pietari, Jeesuksen Kristuksen apostoli, valituille muukalaisille, jotka asuvat hajallaan Pontossa, Galatiassa, Kappadokiassa, Aasian maakunnassa ja Bityniassa,',
        2: 'ja jotka Isän Jumalan edeltämääräämisen mukaan ovat Hengen pyhityksessä valitut kuuliaisuuteen Jeesusta Kristusta kohtaan ja hänen verellään vihmottaviksi. Lisääntyköön teille armo ja rauha!',
        3: 'Ylistetty olkoon meidän Herramme Jeesuksen Kristuksen Jumala ja Isä. Hän on suuren laupeutensa mukaan uudestisynnyttänyt meidät elävään toivoon Jeesuksen Kristuksen kuolleistanousemisen kautta,',
        4: 'turmeltumattomaan, saastumattomaan ja katoamattomaan perintöön. Se on taivaissa säilytettynä teitä varten,',
        5: 'jotka Jumalan voimasta uskon kautta varjellutte pelastukseen, joka on valmiina ilmoitettavaksi viimeisenä aikana.',
        6: 'Siitä [te] riemuitsette, vaikka nyt, jos se on tarpeen, kärsittekin vähän aikaa murhetta monenlaisissa kiusauksissa,',
        7: 'että teidän uskonne koetuksenkestävyys havaittaisiin paljoa kallisarvoisemmaksi kuin katoava kulta, joka kuitenkin tulessa koetellaan, ja koituisi kiitokseksi, ylistykseksi ja kunniaksi Jeesuksen Kristuksen ilmestyessä.',
        8: 'Häntä [te] rakastatte, vaikka ette ole häntä nähneet, häneen [te] uskotte, vaikka ette häntä nyt näe, ja riemuitsette sanomattomalla ja kirkastuneella ilolla,',
        9: 'sillä [te] saavutatte uskonne päämäärän, sielujen pelastuksen.',
        10: 'Tätä pelastusta ovat etsineet ja tutkineet profeetat, jotka ovat profetoineet teille tulevasta armosta,',
        11: 'ovat tutkineet, mihin tai millaiseen aikaan heissä oleva Kristuksen Henki osoitti todistaessaan edeltäpäin Kristusta kohtaavista kärsimyksistä ja niiden jälkeen tulevasta kunniasta.',
        12: 'Heille, koska he eivät palvelleet itseään, vaan meitä, ilmoitettiin se, mikä on nyt teille julistettu niiden kautta, jotka taivaasta lähetetyssä Pyhässä Hengessä ovat teille evankeliumia julistaneet. Sitä enkelitkin haluavat kumartua katsomaan.',
        13: 'Vyöttäkää sen tähden mielenne lanteet ja olkaa raittiit. Pankaa täysi toivonne siihen armoon, joka tuodaan teille Jeesuksen Kristuksen ilmestymisessä.',
        14: 'Niin kuin kuuliaisten lasten tulee, älkää mukautuko niiden himojen mukaan, joissa elitte ennen tietämättömyydessänne,',
        15: 'vaan sen Pyhän mukaan, joka on teidät kutsunut. Olkaa tekin kaikessa vaelluksessanne pyhiä.',
        16: 'Sillä kirjoitettu on: "Olkaa pyhät, sillä minä olen pyhä."',
        17: 'Ja jos Isänänne huudatte avuksi häntä, joka tuomitsee henkilöön katsomatta jokaisen hänen tekonsa mukaan, niin vaeltakaa pelossa tämä muukalaisuutenne aika.',
        18: 'Tietäkää, ettette ole millään katoavalla, ette hopealla ettekä kullalla, lunastetut turhasta, isiltä peritystä vaelluksestanne,',
        19: 'vaan Kristuksen kalliilla verellä, niin kuin virheettömän ja tahrattoman karitsan.',
        20: 'Hänet oli tosin edeltä tiedetty jo ennen maailman perustamista, mutta vasta viimeisinä aikoina hänet on ilmoitettu teitä varten,',
        21: 'jotka uskotte hänen kauttaan Jumalaan, joka herätti hänet kuolleista ja antoi hänelle kirkkauden, niin että uskonne on myös toivo Jumalaan.',
        22: 'Puhdistakaa sielunne totuuden kuuliaisuudessa vilpittömään veljesrakkauteen ja rakastakaa toisianne hartaasti puhtaasta sydämestä,',
        23: 'te, jotka olette uudestisyntyneet, ette katoavasta, vaan katoamattomasta siemenestä, Jumalan elävän ja iäti pysyvän sanan kautta.',
        24: 'Sillä: "kaikki liha on kuin ruoho, ja kaikki ihmiskunnia kuin ruohon kukka. Ruoho kuivuu, ja sen kukka varisee,',
        25: 'mutta Herran sana pysyy iankaikkisesti." Tämä on se sana, joka on teille ilosanomana julistettu.',
    },
    2: {
        1: 'Pankaa siis pois kaikki pahuus ja kaikki vilppi, teeskentely ja kateus sekä kaikki panettelu,',
        2: 'ja halutkaa kuin vastasyntyneet lapset sanan väärentämätöntä maitoa, jotta siitä kasvaisitte,',
        3: 'jos "olette maistaneet, että Herra on hyvä".',
        4: 'Tulkaa hänen luokseen, elävän kiven luo, jonka ihmiset tosin ovat hylänneet, mutta joka on Jumalan edessä valittu, kallis,',
        5: 'ja rakentukaa itsekin elävinä kivinä hengelliseksi rakennukseksi, pyhäksi papistoksi uhraamaan hengellisiä uhreja, jotka Jeesuksen Kristuksen kautta ovat Jumalalle mieluisia.',
        6: 'Sillä Raamatussa sanotaan: "Katso, minä lasken Siioniin valitun, kallisarvoisen kulmakiven. Se, joka häneen uskoo, ei joudu häpeään."',
        7: 'Teille siis, jotka uskotte, se on kallis, mutta niille, jotka eivät usko, "se kivi, jonka rakentajat hylkäsivät, on tullut kulmakiveksi"',
        8: 'ja "kompastuskiveksi ja loukkauskallioksi." He kompastuvat sanaan, koska eivät tottele sitä. Siihen heidät on pantukin.',
        9: 'Mutta te olette "valittu suku, kuninkaallinen papisto, pyhä kansa ja omaisuuskansa julistaaksenne sen suuria tekoja", joka on pimeydestä kutsunut teidät ihmeelliseen valkeuteensa;',
        10: 'te, jotka ennen "ette olleet kansa", mutta nyt olette "Jumalan kansa", jotka ennen "ette olleet armahdettuja", mutta nyt "olette armahdetut."',
        11: 'Rakkaani, kuin vieraita ja muukalaisia minä kehotan teitä pidättymään lihallisista himoista, jotka sotivat sielua vastaan,',
        12: 'ja vaeltamaan oikein pakanoiden keskuudessa, että he siitä, mistä he parjaavat teitä kuin pahantekijöitä, teidän hyvien tekojenne tähden niitä katsellessaan, ylistäisivät Jumalaa tilinteon päivänä.',
        13: 'Olkaa siis alamaisia kaikelle inhimilliselle järjestykselle Herran tähden, sekä kuninkaalle, joka on ylin,',
        14: 'että käskynhaltijoille, jotka hän on lähettänyt pahaa tekeville rangaistukseksi, mutta hyvää tekeville kiitokseksi,',
        15: 'koskapa näin on Jumalan tahto, että hyvää tekemällä vaiennatte typerien ihmisten tietämättömyyden –',
        16: 'niin kuin vapaat, ei niin kuin ne, joilla vapaus on pahuuden verhona, vaan niin kuin Jumalan orjat.',
        17: 'Kunnioittakaa kaikkia, rakastakaa veljiä, pelätkää Jumalaa, kunnioittakaa kuningasta.',
        18: 'Palvelijat, olkaa kaikella pelolla isännillenne alamaisia, ei ainoastaan hyville ja lempeille, vaan tylyillekin.',
        19: 'Sillä on armoa, että joku omantunnon tähden Jumalan edessä kestää vaivoja syyttömästi kärsien.',
        20: 'Sillä mitä kiitettävää siinä on, jos olette kärsivällisiä silloin, kun teitä ruoskitaan syntienne tähden? Mutta jos olette kärsivällisiä, kun hyvien tekojenne tähden kärsitte, se on armoa Jumalan edessä.',
        21: 'Sillä siihen [te] olette kutsutut, koska Kristuskin kärsi meidän puolestamme jättäen meille esikuvan, jotta noudattaisitte hänen jälkiään,',
        22: 'joka "ei syntiä tehnyt ja jonka suusta ei petosta löytynyt",',
        23: 'joka häntä herjattaessa ei herjannut takaisin, joka kärsiessään ei uhannut, vaan jätti asiansa sen haltuun, joka tuomitsee vanhurskaasti,',
        24: 'joka "itse kantoi syntimme" ruumiissaan ristinpuulle, jotta me synneistä pois kuolleina eläisimme vanhurskaudelle. Hänen "haavojensa kautta [te] olette parannetut."',
        25: 'Sillä [te] olitte "eksyksissä kuin lampaat", mutta nyt olette palanneet sielujenne paimenen ja kaitsijan luo.',
    },
    3: {
        1: 'Samoin, vaimot, olkaa alamaisia omille miehillenne, että nekin, jotka ehkä eivät ole kuuliaisia sanalle, vaimojen vaelluksen kautta ilman sanojakin voitettaisiin,',
        2: 'kun he katselevat, kuinka te vaellatte puhtaina ja pelossa.',
        3: 'Älköön kaunistuksenne olko ulkonaista: ei hiusten palmikointia, kultakorujen kantamista tai hienoihin vaatteisiin pukeutumista,',
        4: 'vaan se olkoon salassa oleva sydämen ihminen, hiljaisen ja rauhaisan hengen katoamattomuudessa. Tämä on Jumalan silmissä kallis.',
        5: 'Sillä näin myös ennen pyhät vaimot, jotka panivat toivonsa Jumalaan, kaunistivat itsensä ja olivat omille miehilleen alamaisia.',
        6: 'Niinpä Saara oli kuuliainen Aabrahamille kutsuen häntä herraksi. Hänen lapsikseen olette tulleet, kun teette sitä, mikä on hyvää, ettekä anna minkään kauhistavan pelästyttää itseänne.',
        7: 'Samoin, miehet, eläkää viisaasti kukin vaimonne kanssa, kuin heikomman astian kanssa, ja osoittakaa heille kunnioitusta, koska he ovat kanssanne elämän armon perillisiä, etteivät rukouksenne estyisi.',
        8: 'Lopuksi: olkaa kaikki yksimielisiä, helläsydämisiä, veljiä rakastavia, armahtavia, ystävällisiä.',
        9: 'Älkää kostako pahaa pahalla, älkää herjausta herjauksella, vaan sitä vastoin siunatkaa, sillä siihen olette kutsutut, että perisitte siunauksen.',
        10: 'Sillä: "joka haluaa rakastaa elämää ja nähdä hyviä päiviä, varjelkoon kielensä pahasta ja huulensa puhumasta vilppiä,',
        11: 'kääntyköön pois pahasta ja tehköön hyvää, etsiköön rauhaa ja pyrkiköön siihen.',
        12: 'Sillä Herran silmät ovat vanhurskaihin päin ja hänen korvansa heidän rukouksiinsa, mutta Herran kasvot ovat pahantekijöitä vastaan."',
        13: 'Ja kuka voi teitä vahingoittaa, jos olette hyvän seuraajia?',
        14: 'Vaan vaikka kärsisittekin vanhurskauden tähden, olette autuaita. "Mutta älkää antako heidän pelkonsa pelästyttää itseänne älkääkä hämmentykö",',
        15: 'vaan pyhittäkää Herra Jumala sydämissänne ja olkaa aina valmiit vastaamaan lempeydellä ja pelolla jokaiselle, joka pyytää teiltä selkoa toivosta, joka teissä on,',
        16: 'pitäen hyvän omantunnon, että ne, jotka parjaavat teidän hyvää vaellustanne Kristuksessa, joutuisivat häpeään siinä, mistä he teitä panettelevat.',
        17: 'Sillä parempi on hyvää tehden kärsiä, jos se on Jumalan tahto, kuin pahaa tehden.',
        18: 'Sillä myös Kristus kärsi kerran syntien tähden, vanhurskas väärien puolesta johdattaakseen meidät Jumalan luo. Hänet tosin kuoletettiin lihassa, mutta tehtiin eläväksi hengessä,',
        19: 'jossa hän myös meni pois ja saarnasi vankeudessa oleville hengille,',
        20: 'jotka muinoin eivät olleet kuuliaisia, kun Jumalan pitkämielisyys odotti Nooan päivinä, silloin kun valmistettiin arkkia, jossa vain jotkut, se on kahdeksan sielua, pelastuivat veden kautta.',
        21: 'Tämän vertauskuvan mukaan vesi pelastaa meidätkin nyt kasteena – joka ei ole lian poistamista ruumiista, vaan hyvän omantunnon liitto Jumalan kanssa – Jeesuksen Kristuksen ylösnousemuksen kautta,',
        22: 'hänen, joka on mennyt taivaaseen ja on Jumalan oikealla puolella. Hänen alleen on alistettu enkelit, vallat ja voimat.',
    },
    4: {
        1: 'Koska siis Kristus on kärsinyt edestämme lihassa, niin ottakaa tekin aseeksenne sama mieli – sillä joka lihassa kärsii, se lakkaa synnistä –',
        2: 'ettette enää eläisi tätä lihassa vielä elettävää aikaa ihmisten himojen, vaan Jumalan tahdon mukaan.',
        3: 'Riittäähän meille, että menneen elämän ajan olette täyttäneet pakanoiden tahtoa vaeltaessanne siveettömyydessä, himoissa, juoppoudessa, ylensyömisissä, juomingeissa ja kauheassa epäjumalien palvelemisessa.',
        4: 'Sen tähden he pitävät outona, ettette juokse heidän kanssaan samaan riettauden virtaan, ja herjaavat.',
        5: 'Mutta he tulevat tekemään tilin hänelle, joka on valmis tuomitsemaan elävät ja kuolleet.',
        6: 'Sillä sitä varten kuolleillekin on julistettu evankeliumi, että he tosin olisivat tuomitut lihassa ihmisten tavalla, mutta että heillä olisi hengessä elämä, kuten Jumala elää.',
        7: 'Mutta kaiken loppu on lähellä. Sen tähden olkaa maltillisia ja raittiita rukoilemaan.',
        8: 'Ennen kaikkea olkoon teidän rakkautenne toisianne kohtaan harras, sillä "rakkaus peittää syntien paljouden".',
        9: 'Olkaa vieraanvaraisia toisianne kohtaan nurisematta.',
        10: 'Palvelkaa toisianne, kukin sillä armolahjalla, minkä on saanut, Jumalan monenlaisen armon hyvinä huoneenhaltijoina.',
        11: 'Jos joku puhuu, puhukoon kuin Jumalan sanoja. Jos joku palvelee, palvelkoon sen voiman mukaan, minkä Jumala antaa, että Jumala tulisi kaikessa kirkastetuksi Jeesuksen Kristuksen kautta. Hänen on kunnia ja valta iäisyyksien iäisyyksiin. Aamen.',
        12: 'Rakkaani, älkää pitäkö outona sitä hellettä, jossa olette ja joka on teille koetukseksi, ikään kuin teille tapahtuisi jotain outoa,',
        13: 'vaan iloitkaa, sitä myöten kuin olette osallisia Kristuksen kärsimyksistä, että te myös iloitsisitte riemuiten hänen kirkkautensa ilmestyessä.',
        14: 'Jos teitä solvataan Kristuksen nimen tähden, olette autuaita, sillä kirkkauden ja Jumalan Henki lepää päällänne. Tosin hän tulee noissa pilkatuksi, mutta teissä kirkastetuksi.',
        15: 'Älköön näet kukaan teistä kärsikö murhaajana, varkaana, pahantekijänä tai sen tähden, että sekaantuu toisen virkaan.',
        16: 'Mutta jos hän kärsii kristittynä, älköön hävetkö, vaan ylistäköön siinä osassaan Jumalaa.',
        17: 'Sillä aika on tuomion alkaa Jumalan huoneesta. Mutta jos se alkaa ensiksi meistä, mikä on niiden loppu, jotka eivät ole kuuliaisia Jumalan evankeliumille?',
        18: 'Ja "jos vanhurskas vaivoin pelastuu, mihin joutuukaan jumalaton ja syntinen?"',
        19: 'Sen tähden, uskokoot myös ne, jotka Jumalan tahdon mukaan kärsivät, sielunsa uskolliselle Luojalle, tehden sitä, mikä on hyvää.',
    },
    5: {
        1: 'Vanhimpia teidän joukossanne siis kehotan, minä, joka myös olen vanhin ja Kristuksen kärsimysten todistaja ja myös osallinen siihen tulevaan kirkkauteen, joka on ilmestyvä:',
        2: 'kaitkaa teille uskottua Jumalan laumaa, ei pakosta, vaan vapaaehtoisesti, ei häpeällisen voiton tähden, vaan sydämen halusta,',
        3: 'ei herroina halliten niitä, jotka ovat teidän osallenne tulleet, vaan ollen laumalle esikuvina,',
        4: 'niin Ylipaimenen ilmestyessä saatte kirkkauden kuihtumattoman seppeleen.',
        5: 'Samoin te, nuoremmat, olkaa vanhimmille alamaisia ja olkaa kaikki toinen toisellenne alamaisia, pukeutukaa keskinäiseen nöyryyteen, sillä "Jumala on ylpeitä vastaan, mutta nöyrille hän antaa armon."',
        6: 'Nöyrtykää siis Jumalan väkevän käden alle, että hän ajallaan teidät korottaisi,',
        7: 'ja: "heittäkää kaikki murheenne hänen päälleen, sillä hän pitää teistä huolen".',
        8: 'Olkaa raittiit, valvokaa. Teidän vastustajanne, perkele, käy ympäri kuin karjuva leijona etsien, kenet nielisi.',
        9: 'Vastustakaa häntä lujina uskossa, tietäen, että samat kärsimykset täytyy teidän veljiennekin maailmassa kestää.',
        10: 'Mutta kaiken armon Jumala, joka on kutsunut meidät iankaikkiseen kirkkauteensa Kristuksessa Jeesuksessa, vähän aikaa kärsittyänne hän on teitä valmistava, teitä tukeva, vahvistava ja lujittava.',
        11: 'Hänen olkoon kunnia ja valta iäisyyksien iäisyyksiin! Aamen.',
        12: 'Silaksen, uskollisen veljen, kautta jona häntä pidän, olen kirjoittanut lyhyesti teille, kehottaen teitä ja vakuuttaen, että armo, jossa olette, on Jumalan todellinen armo.',
        13: 'Tervehdyksen lähettää teille Babylonissa oleva seurakunta, valittu niin kuin tekin, ja poikani Markus.',
        14: 'Tervehtikää toisianne rakkauden suudelmalla. Rauha teille kaikille, jotka Kristuksessa Jeesuksessa olette! Aamen.',
    },
}
